package com.example.minicommerce.notification.infrastructure;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="points_ledger",uniqueConstraints=@UniqueConstraint(name="ux_points_order_reason",columnNames={"order_id","reason"}))public class PointsLedgerEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="user_id",nullable=false)private Long userId;@Column(name="order_id",nullable=false)private UUID orderId;@Column(nullable=false,length=50)private String reason;@Column(nullable=false)private int points;@Column(name="created_at",nullable=false)private Instant createdAt;protected PointsLedgerEntity(){}public PointsLedgerEntity(Long u,UUID o,int p,Instant n){userId=u;orderId=o;reason="ORDER_PAID";points=p;createdAt=n;}}
